"""Audit existing prescribed ADMAS separately from artificial Engine mass scaling."""
from ablate_aircraft_a48 import *

def run():
 guard();c=read(DEC);d=OUT/c['case'];n=read(d/'generation.json')['name'];assert not (d/'engine.log').exists();baseline=(ROOT/c['reference_Starter_report']).read_text();ad=float(re.search(r'TOTAL ADDED MASS\s*=\s*([\d.E+\-]+)',baseline).group(1));old=read(d/'mass_review.json');assert old['reference_mass_g']==old['variant_mass_g'] and old['added_mass_g']==ad;assert read(d/'starter_gate.json')['errors']==0;assert read(d/'input_ablation_review.json')['all_other_keyword_sections_identical'];p=OUT/'whole_mass_reader_preflight_addendum.json';assert not p.exists();dump(p,{'created_utc':now(),'before_first_Engine_on_this_state':True,'prior_failed_review_retained':rel(d/'mass_review.json'),'prior_reader_error':'Treated Starter TOTAL ADDED MASS as artificial mass scaling. It is existing prescribed nonstructural ADMAS in both original and variant; Engine ADDED MASS counter is checked separately.','reference_prescribed_nonstructural_mass_g':ad,'variant_prescribed_nonstructural_mass_g':old['added_mass_g'],'total_mass_unchanged':True,'center_unchanged':old['reference_center_mm']==old['variant_center_mm'],'all_ADMAS_input_sections_identical':True,'new_mass_compensation':False,'thresholds_unchanged':True,'physical_input_or_restart_changed':False,'Starter_warnings_kept':read(d/'starter_gate.json')['warnings'],'new_Starter_rerun':False});normal=launcher.execute(d,n);txt=(d/'engine.log').read_text(errors='replace');mass=None;scaled=None
 for f in d.glob(n+'T[0-9][0-9]'):
  if win_execute(RUNTIME/'th_to_csv_win64.exe',[f.name],d,f.name+'.converter.log',120,env()):
   H=histories(f.with_suffix('.csv'));mass=float(H['MASS'][0]);scaled=float(abs(H['ADDED MASS']).max())
 result={'created_utc':now(),'native_NORMAL_exit0':normal,'CHECK_begin_end':'BEGIN IMPLICIT MODEL CHECKING' in txt and 'END IMPLICIT MODEL CHECKING' in txt,'ASSEMC_KIJ_abort_seen':'assemc_kij_' in txt,'TYPE25_implicit_ignored_warnings':txt.count('INTERFACE TYPE 25 IS NOT AVAILABLE'),'Starter_errors':read(d/'starter_gate.json')['errors'],'Starter_warnings':read(d/'starter_gate.json')['warnings'],'Starter_total_mass_g':old['variant_mass_g'],'unchanged_prescribed_nonstructural_mass_g':ad,'native_initial_global_mass_g':mass,'Engine_added_mass_scaling_g':scaled,'native_total_mass_pass':mass is not None and abs(mass-old['variant_mass_g'])<=1e-6*old['variant_mass_g'],'no_Engine_added_mass_scaling':scaled is not None and scaled<=1e-9*old['variant_mass_g'],'RBE3_removed':368,'whole_impact_qualified':False,'constraints_and_mass_redistribution_changed_explicitly':True,'physical_duration_credit_s':0};dump(d/'ablation_result.json',result);print(result,flush=True)

if __name__=='__main__':run()
